// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 _value, bytes calldata _data) public {
        vm.assume(_value <= address(this).balance);
        address payable target = payable(address(new Target()));
        uint256 targetBalanceBefore = address(target).balance;
        vm.deal(address(c), _value);
        vm.prank(c.owner());
        try c.sendMoney(target, _value, _data) {}
        catch {}
        uint256 targetBalanceAfter = address(target).balance;
        assertTrue(targetBalanceAfter - targetBalanceBefore >= _value);
    }
}

contract Target {
    fallback() external payable {}
    receive() external payable {}
}
